-- 세트 224: kubectl 출력에서 원하는 값만 뽑기: jsonpath, range, 필터, custom-columns, sort-by
-- 기본기 사다리(docs/specs/spec_foundations_ladder.md). 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (224, 1, 'JSON 구조 눈으로 보기', 'Pod 목록을 **JSON** 으로 `/tmp/pods.json` 에 저장하고 열어 보세요. 가장 바깥은 `List` 이고, Pod 들은 `items` 배열 안에 들어 있습니다.', '`kubectl get pods -o json` 의 결과를 `>` 로 파일에 저장하세요. 저장한 뒤 `head -n 20 /tmp/pods.json` 으로 맨 위를 읽어 보세요.', 'kubectl get pods -n $NS -o json > /tmp/pods.json
head -n 20 /tmp/pods.json

# 맨 위 "kind": "List", 그 아래 "items": [ Pod, Pod, ... ]
# Pod 하나는 metadata(이름·레이블), spec(원하는 상태), status(현재 상태)로 나뉜다. 다음 문제부터는 이 구조에서 값 하나를 "경로"로 짚어 뽑는다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.json; kubectl run web-1 --image=nginx:1.25 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run web-2 --image=nginx:1.24 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run db-1 --image=busybox:1.36 --labels=app=db,tier=back -n $NS -- sleep 3600 >/dev/null 2>&1; kubectl annotate pod web-1 example.io/owner=team-a -n $NS --overwrite >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 pod/web-2 pod/db-1 -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ -s /tmp/pods.json ] ) && ( grep -q ''\\"items\\"'' /tmp/pods.json ) && ( grep -q ''\\"name\\": \\"db-1\\"'' /tmp/pods.json )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/pods.json ]"]}, {"label": "items 배열이 있다", "cmd": ["sh", "-c", "grep -q ''\\"items\\"'' /tmp/pods.json"]}, {"label": "Pod db-1 이 들어 있다", "cmd": ["sh", "-c", "grep -q ''\\"name\\": \\"db-1\\"'' /tmp/pods.json"]}]', '[{"title": "kubectl 빠른 참조 (JSONPath, custom-columns, sort-by)", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "JSONPath 지원", "url": "https://kubernetes.io/docs/reference/kubectl/jsonpath/"}]'),
  (224, 2, '첫 번째 Pod 이름만 뽑기', '첫 번째 Pod 의 **이름만** `/tmp/first.txt` 에 저장하세요. 경로는 JSON 구조를 따라 점(`.`)으로 이어 씁니다. 참고로 `jsonpath` 출력 끝에는 줄바꿈이 없어서, 화면에 바로 찍으면 다음 프롬프트가 붙어 나와요.', '`-o jsonpath=''{...}''` 안에 `.items[0].metadata.name` 을 넣어요. 번호는 0부터 셉니다.', 'kubectl get pods -n $NS -o jsonpath=''{.items[0].metadata.name}'' > /tmp/first.txt
cat /tmp/first.txt; echo

# {.items[0].metadata.name} : items 의 0번째 → metadata → name
# 화면에 찍을 때는 뒤에 ; echo 를 붙이면 줄이 바뀐다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.json; kubectl run web-1 --image=nginx:1.25 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run web-2 --image=nginx:1.24 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run db-1 --image=busybox:1.36 --labels=app=db,tier=back -n $NS -- sleep 3600 >/dev/null 2>&1; kubectl annotate pod web-1 example.io/owner=team-a -n $NS --overwrite >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 pod/web-2 pod/db-1 -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/first.txt)\\" = db-1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "값이 db-1 이다 (이름 순 첫 Pod)", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/first.txt)\\" = db-1 ]"]}]', '[{"title": "kubectl 빠른 참조 (JSONPath, custom-columns, sort-by)", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "JSONPath 지원", "url": "https://kubernetes.io/docs/reference/kubectl/jsonpath/"}]'),
  (224, 3, '모든 Pod 이름을 한 줄에 하나씩', '모든 Pod 의 이름을 **한 줄에 하나씩** `/tmp/names.txt` 에 저장하세요. 목록 전체를 돌 때는 `{range .items[*]}` 와 `{end}` 사이에 뽑을 값을 적습니다.', '`{range .items[*]}{.metadata.name}{"\\n"}{end}` 처럼 값 뒤에 `{"\\n"}` 으로 줄을 바꿔 주세요.', 'kubectl get pods -n $NS -o jsonpath=''{range .items[*]}{.metadata.name}{"\\n"}{end}'' > /tmp/names.txt
cat /tmp/names.txt

# range 는 items 의 모든 원소를 하나씩 돌며 안쪽 식을 실행한다. {"\\n"} 가 없으면 이름이 한 줄에 붙는다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.json; kubectl run web-1 --image=nginx:1.25 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run web-2 --image=nginx:1.24 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run db-1 --image=busybox:1.36 --labels=app=db,tier=back -n $NS -- sleep 3600 >/dev/null 2>&1; kubectl annotate pod web-1 example.io/owner=team-a -n $NS --overwrite >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 pod/web-2 pod/db-1 -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/names.txt)\\" -eq 3 ] ) && ( [ \\"$(paste -sd, /tmp/names.txt)\\" = db-1,web-1,web-2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/names.txt)\\" -eq 3 ]"]}, {"label": "이름이 db-1, web-1, web-2 이다", "cmd": ["sh", "-c", "[ \\"$(paste -sd, /tmp/names.txt)\\" = db-1,web-1,web-2 ]"]}]', '[{"title": "kubectl 빠른 참조 (JSONPath, custom-columns, sort-by)", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "JSONPath 지원", "url": "https://kubernetes.io/docs/reference/kubectl/jsonpath/"}]'),
  (224, 4, '이름과 이미지를 함께 뽑기', '모든 Pod 의 **이름과 첫 컨테이너 이미지**를 탭으로 구분해 한 줄에 하나씩 `/tmp/images.txt` 에 저장하세요. (예: `web-1`, 탭, `nginx:1.25`)', '앞 문제의 `range` 안에 값을 두 개 넣고, 그 사이에 `{"\\t"}` 를 둡니다. 이미지 경로는 `.spec.containers[0].image` 예요.', 'kubectl get pods -n $NS -o jsonpath=''{range .items[*]}{.metadata.name}{"\\t"}{.spec.containers[0].image}{"\\n"}{end}'' > /tmp/images.txt
cat /tmp/images.txt

# {"\\t"} 는 탭. 이름 옆에 이미지가 오는 표 모양이 된다. 스크립트에서 awk 로 칸을 나눠 쓰기 좋다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.json; kubectl run web-1 --image=nginx:1.25 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run web-2 --image=nginx:1.24 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run db-1 --image=busybox:1.36 --labels=app=db,tier=back -n $NS -- sleep 3600 >/dev/null 2>&1; kubectl annotate pod web-1 example.io/owner=team-a -n $NS --overwrite >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 pod/web-2 pod/db-1 -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/images.txt)\\" -eq 3 ] ) && ( [ \\"$(awk -F\\"\\\\t\\" ''{print $1\\"=\\"$2}'' /tmp/images.txt | paste -sd,)\\" = db-1=busybox:1.36,web-1=nginx:1.25,web-2=nginx:1.24 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/images.txt)\\" -eq 3 ]"]}, {"label": "이름과 이미지가 짝으로 맞다", "cmd": ["sh", "-c", "[ \\"$(awk -F\\"\\\\t\\" ''{print $1\\"=\\"$2}'' /tmp/images.txt | paste -sd,)\\" = db-1=busybox:1.36,web-1=nginx:1.25,web-2=nginx:1.24 ]"]}]', '[{"title": "kubectl 빠른 참조 (JSONPath, custom-columns, sort-by)", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "JSONPath 지원", "url": "https://kubernetes.io/docs/reference/kubectl/jsonpath/"}]'),
  (224, 5, 'Deployment 의 이미지 경로', 'Deployment `web` 의 **첫 번째 컨테이너 이미지**를 뽑는 경로입니다. 빈칸을 채우세요. (Pod 와 달리 Deployment 는 Pod 모양이 `template` 안에 들어 있어요.)', 'Pod 에서는 `.spec.containers` 였죠. Deployment 는 그 앞에 `template` 이 한 겹 더 있어요.', NULL, NULL, '[]', 'fill', '["containers", "container", "images", "template"]', NULL, 'Deployment 의 `.spec.template` 이 "만들 Pod 의 설계도"이고, 그 안의 `.spec.containers` 가 Pod 와 같은 모양입니다. 그래서 Deployment 는 `.spec.template.spec.containers[0].image`, Pod 는 `.spec.containers[0].image` 입니다.', '[0]', 'kubectl get deploy web -o jsonpath=''{.spec.template.spec.{0}[0].image}''', NULL, NULL),
  (224, 6, '점이 들어 있는 키 읽기', 'Pod `web-1` 의 어노테이션 **`example.io/owner`** 의 값을 `/tmp/owner.txt` 에 저장하세요. 키 이름 안에 점이 있어서 그냥 쓰면 경로로 오해됩니다.', '키 안의 점 앞에 역슬래시를 붙여 `example\\.io/owner` 처럼 씁니다. 어노테이션 경로는 `.metadata.annotations.키` 예요.', 'kubectl get pod web-1 -n $NS -o jsonpath=''{.metadata.annotations.example\\.io/owner}'' > /tmp/owner.txt
cat /tmp/owner.txt; echo

# 점(.)은 경로 구분자라서, 키 이름 안의 점은 \\. 로 막아야 한다
# 레이블·어노테이션 키에는 kubernetes.io/... 처럼 점이 자주 들어간다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.json; kubectl run web-1 --image=nginx:1.25 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run web-2 --image=nginx:1.24 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run db-1 --image=busybox:1.36 --labels=app=db,tier=back -n $NS -- sleep 3600 >/dev/null 2>&1; kubectl annotate pod web-1 example.io/owner=team-a -n $NS --overwrite >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 pod/web-2 pod/db-1 -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/owner.txt)\\" = team-a ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "값이 team-a 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/owner.txt)\\" = team-a ]"]}]', '[{"title": "kubectl 빠른 참조 (JSONPath, custom-columns, sort-by)", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "JSONPath 지원", "url": "https://kubernetes.io/docs/reference/kubectl/jsonpath/"}]'),
  (224, 7, '조건으로 골라서 뽑기', '지금 **Running** 인 Pod 의 이름만 `/tmp/running.txt` 에 저장하세요. 잘못된 이미지로 만든 Pod `bad-1` 은 Running 이 아니라서 빠져야 합니다. 이름은 공백으로 이어져 나와도 됩니다.', '`[ ]` 안에 `?(@.조건)` 을 쓰면 걸러져요. `@` 는 지금 보는 항목이고, 비교하는 문자열은 큰따옴표로 감쌉니다: `?(@.status.phase=="Running")`', 'kubectl get pods -n $NS -o jsonpath=''{.items[?(@.status.phase=="Running")].metadata.name}'' > /tmp/running.txt
cat /tmp/running.txt; echo

# [?(@.조건)] : 조건이 참인 원소만 고른다. 장애 때 "안 뜨는 Pod 만" 골라낼 때도 같은 식이다 (!= 로 바꾸면 된다)', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.json; kubectl run web-1 --image=nginx:1.25 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run web-2 --image=nginx:1.24 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run db-1 --image=busybox:1.36 --labels=app=db,tier=back -n $NS -- sleep 3600 >/dev/null 2>&1; kubectl annotate pod web-1 example.io/owner=team-a -n $NS --overwrite >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 pod/web-2 pod/db-1 -n $NS --timeout=120s >/dev/null 2>&1; true; kubectl run bad-1 --image=nginx:no-such-tag-xyz -n $NS >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(tr \\" \\" \\"\\\\n\\" < /tmp/running.txt | sort | paste -sd,)\\" = db-1,web-1,web-2 ] ) && ( ! grep -q bad-1 /tmp/running.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Running Pod 만 있다", "cmd": ["sh", "-c", "[ \\"$(tr \\" \\" \\"\\\\n\\" < /tmp/running.txt | sort | paste -sd,)\\" = db-1,web-1,web-2 ]"]}, {"label": "bad-1 은 없다", "cmd": ["sh", "-c", "! grep -q bad-1 /tmp/running.txt"]}]', '[{"title": "kubectl 빠른 참조 (JSONPath, custom-columns, sort-by)", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "JSONPath 지원", "url": "https://kubernetes.io/docs/reference/kubectl/jsonpath/"}]'),
  (224, 8, '열을 골라 표로 보기', '이름과 이미지를 **열 제목과 함께** 표로 `/tmp/table.txt` 에 저장하세요. 열 제목은 `NAME`, `IMAGE` 입니다.', '`-o custom-columns=열제목:경로,열제목:경로` 형식이에요. 경로는 `jsonpath` 와 같지만 `{}` 는 쓰지 않아요.', 'kubectl get pods -n $NS -o custom-columns=NAME:.metadata.name,IMAGE:.spec.containers[0].image > /tmp/table.txt
cat /tmp/table.txt

# 열제목:경로 를 쉼표로 이어 쓴다. 사람이 읽기 좋은 표가 필요할 때 jsonpath 보다 편하다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.json; kubectl run web-1 --image=nginx:1.25 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run web-2 --image=nginx:1.24 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run db-1 --image=busybox:1.36 --labels=app=db,tier=back -n $NS -- sleep 3600 >/dev/null 2>&1; kubectl annotate pod web-1 example.io/owner=team-a -n $NS --overwrite >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 pod/web-2 pod/db-1 -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(head -n 1 /tmp/table.txt | tr -s \\" \\")\\" = \\"NAME IMAGE\\" ] ) && ( grep -Eq \\"^web-1 +nginx:1.25$\\" /tmp/table.txt ) && ( [ \\"$(wc -l < /tmp/table.txt)\\" -eq 4 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "제목 줄이 NAME IMAGE 이다", "cmd": ["sh", "-c", "[ \\"$(head -n 1 /tmp/table.txt | tr -s \\" \\")\\" = \\"NAME IMAGE\\" ]"]}, {"label": "web-1 의 이미지가 맞다", "cmd": ["sh", "-c", "grep -Eq \\"^web-1 +nginx:1.25$\\" /tmp/table.txt"]}, {"label": "제목 + 3행이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/table.txt)\\" -eq 4 ]"]}]', '[{"title": "kubectl 빠른 참조 (JSONPath, custom-columns, sort-by)", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "JSONPath 지원", "url": "https://kubernetes.io/docs/reference/kubectl/jsonpath/"}]'),
  (224, 9, '만든 순서로 정렬하기', 'Pod 를 **오래된 것부터** 정렬해 이름만 `/tmp/old.txt` 에 저장하세요. 기본 조회는 이름 순이라서, 만든 순서와 다릅니다. (`pod/` 접두사가 붙어도 됩니다.)', '`--sort-by=` 뒤에 `{}` 없이 경로를 씁니다. 만든 시각은 `.metadata.creationTimestamp` 예요.', 'kubectl get pods -n $NS --sort-by=.metadata.creationTimestamp -o name > /tmp/old.txt
cat /tmp/old.txt

# --sort-by=경로 : 그 값으로 오름차순 정렬. 거꾸로 보려면 뒤에 tac 같은 도구를 쓴다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl run zeta --image=busybox:1.36 -n $NS -- sleep 3600 >/dev/null 2>&1; sleep 2; kubectl run alpha --image=busybox:1.36 -n $NS -- sleep 3600 >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(sed \\"s#pod/##\\" /tmp/old.txt | paste -sd,)\\" = zeta,alpha ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "만든 순서(zeta, alpha)이다", "cmd": ["sh", "-c", "[ \\"$(sed \\"s#pod/##\\" /tmp/old.txt | paste -sd,)\\" = zeta,alpha ]"]}]', '[{"title": "kubectl 빠른 참조 (JSONPath, custom-columns, sort-by)", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "JSONPath 지원", "url": "https://kubernetes.io/docs/reference/kubectl/jsonpath/"}]'),
  (224, 10, '두 번째 컨테이너 이미지의 경로', '아래 JSON 조각에서 **두 번째 컨테이너의 이미지**(`busybox`)를 뽑는 jsonpath 는 어느 것일까요?

```
"spec": { "containers": [ { "name": "app", "image": "nginx:1.25" }, { "name": "log", "image": "busybox" } ] }
```', '배열 번호는 1부터가 아니라 0부터 셉니다.', NULL, NULL, '[]', 'choice', '["{.spec.containers[2].image}", "{.spec.containers[1].image}", "{.spec.containers.image[1]}", "{.spec.containers[*].image[1]}"]', 1, '`containers` 는 배열이고 번호는 0부터라서, 두 번째는 `[1]` 입니다. 번호는 배열 이름 바로 뒤에 붙여요. `[*]` 는 모든 원소를 뜻합니다.', NULL, NULL, NULL, NULL),
  (224, 11, 'Secret 값 풀어서 읽기', 'Secret `db-pass` 의 **`password`** 값을 사람이 읽을 수 있게 풀어서 `/tmp/pass.txt` 에 저장하세요. Secret 의 데이터는 base64 로 인코딩되어 있습니다.', '`jsonpath` 로 `.data.password` 를 뽑아 `base64 -d` 로 넘기세요. (`-d` 는 decode)', 'kubectl get secret db-pass -n $NS -o jsonpath=''{.data.password}'' | base64 -d > /tmp/pass.txt
cat /tmp/pass.txt; echo

# Secret 의 .data 값은 base64 로 적혀 있다 (암호화가 아니다!). base64 -d 로 풀면 평문이 나온다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl create secret generic db-pass --from-literal=password=s3cr3t-pw -n $NS >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/pass.txt)\\" = s3cr3t-pw ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "풀린 값이 s3cr3t-pw 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/pass.txt)\\" = s3cr3t-pw ]"]}]', '[{"title": "kubectl 빠른 참조 (JSONPath, custom-columns, sort-by)", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "JSONPath 지원", "url": "https://kubernetes.io/docs/reference/kubectl/jsonpath/"}]'),
  (224, 12, 'Pod 이미지별 개수 세기', 'Pod 들이 쓰는 이미지를 **많이 쓰는 순서로 개수와 함께** 보는 조합입니다. 순서에 맞게 놓아 보세요.', '뽑기 → 정렬 → 세기 → 순위 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl get pods -o jsonpath=''{range .items[*]}{.spec.containers[0].image}{\\"\\\\n\\"}{end}''`", "`sort`", "`uniq -c`", "`sort -rn`"]', NULL, '`kubectl` 로 이미지를 한 줄에 하나씩 뽑고, `uniq` 는 이웃한 줄만 합치므로 먼저 `sort` 를 거친 뒤 `uniq -c` 로 세고, 마지막에 `sort -rn` 으로 많은 순서로 정렬합니다. 로그 분석에서 쓰는 조합과 같아요.', '[0, 1, 2, 3]', NULL, NULL, NULL);
